def _deploy_docker_image_from_local_repo(
    image_info_path: str,
    docker_repository: str,
    auth_method: AuthorizationType = AuthorizationType.LOCAL_ACCOUNT,
    vault_endpoint: str | None = None,
    vault_secret: str | None = None,
) -> str:
