class File(
    PathReprProvider,
    Persistent,
    Implicit,
    PropertyManager,
    RoleManager,
    Item_w__name__,
    Cacheable
):
    precondition = ''
    size = None
    def _if_modified_since_request_handler(self, REQUEST, RESPONSE):
        header = REQUEST.get_header('If-Modified-Since', None)
        if header is not None:
            header = header.split(';')[0]
            try:
                mod_since = int(DateTime(header).timeTime())
            except Exception:
                mod_since = None
            if mod_since is not None:
                if self._p_mtime:
                    last_mod = int(self._p_mtime)
                else:
                    last_mod = 0
                if last_mod > 0 and last_mod <= mod_since:
                    RESPONSE.setHeader(
                        'Last-Modified', rfc1123_date(self._p_mtime)
                    )
                    RESPONSE.setHeader('Content-Type', self.content_type)
                    RESPONSE.setHeader('Accept-Ranges', 'bytes')
                    RESPONSE.setStatus(304)
                    return True
    def index_html(self, REQUEST, RESPONSE):
        """
        The default view of the contents of a File or Image.
        Returns the contents of the file or image.  Also, sets the
        Content-Type HTTP header to the objects content type.
        """
        if self._if_modified_since_request_handler(REQUEST, RESPONSE):
            self.ZCacheable_set(None)
            return b''
        if self.precondition and hasattr(self, str(self.precondition)):
            c = getattr(self, str(self.precondition))
            if hasattr(c, 'isDocTemp') and c.isDocTemp:
                c(REQUEST['PARENTS'][1], REQUEST)
            else:
                c()
        if self._range_request_handler(REQUEST, RESPONSE):
            return b''
        RESPONSE.setHeader('Last-Modified', rfc1123_date(self._p_mtime))
        RESPONSE.setHeader('Content-Type', self.content_type)
        RESPONSE.setHeader('Content-Length', self.size)
        RESPONSE.setHeader('Accept-Ranges', 'bytes')
        if self.ZCacheable_isCachingEnabled():
            result = self.ZCacheable_get(default=None)
            if result is not None:
                return result
        self.ZCacheable_set(None)
        data = self.data
        if isinstance(data, bytes):
            RESPONSE.setBase(None)
            return data
        while data is not None:
            RESPONSE.write(data.data)
            data = data.next
        return b''
    def manage_DAVget(self):
        """Return body for WebDAV."""
        RESPONSE = self.REQUEST.RESPONSE
        if self.ZCacheable_isCachingEnabled():
            result = self.ZCacheable_get(default=None)
            if result is not None:
                RESPONSE.setHeader('Content-Length', self.size)
                return result
        data = self.data
        if isinstance(data, bytes):
            RESPONSE.setBase(None)
            return data
        while data is not None:
            RESPONSE.write(data.data)
            data = data.next
        return b''

def format_data(data, format_iso_dates=False, format_money_values=False):
    if data is None:
        return ""
    elif isinstance(data, Money):
        if format_money_values:
            return format_money(data)
        return float(data.as_rounded().value)
    elif isinstance(data, Decimal):
        exponent = abs(data.normalize().as_tuple().exponent)
        return floatformat(data, min(exponent, 10))
    elif callable(data):
        return force_text(data())
    elif isinstance(data, Promise):
        return force_text(data)
    elif isinstance(data, models.Model):
        return force_text(data)
    elif isinstance(data, datetime):
        if format_iso_dates:
            return data.isoformat()
        return get_locally_formatted_datetime(data)
    return data
    def write_data_table(self, report, report_data, has_totals=True):
        self.data.append([c["title"] for c in report.schema])
        for datum in report_data:
            datum = report.read_datum(datum)
            self.data.append([format_data(data, format_iso_dates=True) for data in datum])
        if has_totals:
            for datum in report.get_totals(report_data):
                datum = report.read_datum(datum)
                self.data.append([format_data(data) for data in datum])
    def _convert_row_to_string(self):
        for cell in self.worksheet[self.worksheet.max_row]:
            if cell.data_type == "f":
                cell.data_type = "s"
    def write_data_table(self, report, report_data, has_totals=True):
        self.worksheet.append([c["title"] for c in report.schema])
        for datum in report_data:
            datum = report.read_datum(datum)
            self.worksheet.append([format_data(data) for data in datum])
            self._convert_row_to_string()
